 std::vector<unsigned char> flipped(colored.size());for(int y=0;y<480;y++)std::copy(colored.begin()+y*800*4,colored.begin()+(y+1)*800*4,flipped.begin()+(479-y)*800*4);png_image png{};png.version=PNG_IMAGE_VERSION;png.width=800;png.height=480;png.format=PNG_FORMAT_RGBA;assert(png_image_write_to_file(&png,"../armor-stand-native-proof.png",0,flipped.data(),0,nullptr));std::cout<<"Native armor stand body/UV, arms/baseplate/small, marker visual semantics, server poses, custom head/main/off hand, invisible equipment, authoritative clearing, vanilla helmet/mace and GL state PASS"<<std::endl;std::_Exit(0);
